class Student:
    count = 0

    def __init__(self, name):
        self.name = name
        Student.count += 1

    @classmethod
    def total(cls):
        return cls.count

    @staticmethod
    def is_valid(name):
        return len(name) > 0

    @property
    def tag(self):
        return "S" + str(Student.count)

a = Student("Ann")
b = Student("Bob")
print(Student.total(), Student.is_valid(""), a.tag, b.tag)

class Bag:
    def __init__(self, items):
        self.items = list(items)

    def __len__(self):
        return len(self.items)

    def __add__(self, other):
        return Bag(self.items + other.items)

    def __eq__(self, other):
        return sorted(self.items) == sorted(other.items)

x = Bag([3, 1])
y = Bag([1, 3])
z = x + y
print(len(z), x == y, x is y, len(x + Bag([])))

memo = {}
calls = 0

def f(n):
    global calls
    calls += 1
    if n <= 1:
        return n
    if n not in memo:
        memo[n] = f(n - 1) + f(n - 2)
    return memo[n]

